      const e = c.t < 0.5 ? 2 * c.t * c.t : 1 - Math.pow(-2 * c.t + 2, 2) / 2; // ゆっくり動き出して、最後はなめらかに吸い込まれる
      const mx = (c.sx + target.x) / 2, my = Math.min(c.sy, target.y) - 60; // 少し弧を描く
